svg.script:

(function() {
  var dot = document.getElementById('dot');
  var counter = document.getElementById('counter');
  var n = 0;
  var t = 0;
  // Pulse loop — proves JS animation runs
  setInterval(function() {
    t += 0.1;
    var r = 20 + Math.sin(t) * 6;
    dot.setAttribute('r', r);
  }, 30);
  // Click counter — proves event handlers work
  dot.addEventListener('click', function() {
    n++;
    counter.textContent = 'click count: ' + n;
  });
})();
